uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// --- AUDIO INPUTS ---
uniform float u_bass;
uniform float u_mid;
uniform float u_treble;

// --- ASSETS ---
uniform sampler2D iChannel0; 
uniform sampler2D iChannel1; 

// --- STANDARD CONTROLS ---
uniform float u_speed;
uniform float u_camera_dist; 
uniform float u_fov;
uniform float u_glow_intensity;

// --- VISUAL CONTROLS ---
uniform float u_turbulence_strength;
uniform float u_cloud_height; // Reused as tunnel radius
uniform float u_color_shift;
uniform float u_density_factor;
uniform float u_tunnel_twist; 
uniform float u_exit_light_size; 
uniform float u_exit_light_bright; 

// --- NEW LUSHNESS CONTROLS ---
uniform float u_bloom_amount;
uniform float u_pulse_speed;
uniform float u_chromatic_aberration;

out vec4 fragColor;

// --- LUMINA MATH LIB ---
#define PI 3.14159265359

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Helper for color variations
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.67);
    return a + b * cos(2.0 * PI * (c * t + d + u_color_shift));
}

// --- MAIN RENDER LOOP ---
void main() {
    // 1. Setup UVs and Ray Direction
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Audio Reactivity Integration
    float bassBoost = u_bass * 0.2;
    float pulse = sin(iTime * u_pulse_speed) * 0.1;

    // Chromatic Aberration offset calculation
    float chroma = u_chromatic_aberration * 0.02 * length(uv);

    // Create the ray direction for a forward-moving perspective
    vec3 rd = normalize(vec3(uv, 1.0 / (u_fov + pulse))); 

    // Animation Time
    float t = iTime * u_speed;

    // Raymarching Variables
    vec4 col = vec4(0.0);
    float dist = u_camera_dist; 
    float stepSize = 0.0;
    float accumGlow = 0.0;

    // --- VOLUMETRIC MARCH ---
    // Increased steps for more "lush" density
    for(int i = 0; i < 100; i++) {

        // Current Position along Ray
        vec3 p = dist * rd;
        p.z += t; // Forward motion

        // Apply twist to the tunnel based on depth
        p.xy *= rot(p.z * u_tunnel_twist + t * 0.05);

        // --- TURBULENCE LOOP (FBM) ---
        // Enhanced with audio for lush movement
        float scale = 2.0;
        float strength = u_turbulence_strength * (1.0 + bassBoost);
        for(int j = 0; j < 5; j++) {
            p += strength * sin(p.yzx * scale + (t * 0.2)) / scale;
            scale *= 1.7; 
        }

        // --- CYLINDRICAL DENSITY CALCULATION ---
        float radius = u_cloud_height * (2.0 + pulse);
        float tunnelDist = length(p.xy) - radius;

        // Calculate Step Size - smaller steps for smoother volume
        float stepFactor = max(abs(tunnelDist), 0.015);
        stepSize = stepFactor * 0.35;

        // Advance Ray
        dist += stepSize;

        // --- COLOR ACCUMULATION ---
        float angle = atan(p.y, p.x);
        float hue = p.z * 0.2 + angle / (2.0 * PI) + (u_mid * 0.2);

        // Lush color mapping
        vec3 baseColor = palette(hue);

        // Glow logic based on proximity to the tunnel wall
        float wallGlow = exp(-abs(tunnelDist) * (12.0 / u_density_factor));

        // Volumetric density accumulation
        float density = wallGlow * (1.0 / (1.0 + dist * 0.3));
        col.rgb += baseColor * density * (u_glow_intensity * 0.04);
        accumGlow += density;

        // Optimization: early exit if color is saturated
        if(dist > 30.0 || col.a > 0.99) break;
    }

    // --- THE LIGHT AT THE END OF THE TUNNEL ---
    float exitGlow = pow(max(0.0, 1.0 - length(uv) / (u_exit_light_size + u_treble * 0.1)), 6.0);
    vec3 exitColor = vec3(0.9, 0.95, 1.0) * exitGlow * u_exit_light_bright;

    // --- POST PROCESSING ---
    vec3 finalCol = col.rgb + exitColor;

    // Add Bloom-like effect based on accumulated glow
    finalCol += col.rgb * u_bloom_amount * 0.5;

    // Contrast and Tone Mapping
    finalCol = smoothstep(-0.05, 1.1, finalCol);
    finalCol = pow(finalCol, vec3(0.85)); // Slight gamma lift for lushness
    finalCol = tanh(finalCol * 1.8); 

    // Subtle Vignette
    float vignette = 1.0 - dot(uv, uv) * 0.4;
    finalCol *= vignette;

    fragColor = vec4(finalCol, 1.0);
}
